/* Learning-room orientation; content stays fixed while reading and writing. */
(()=>{
 const rooms={academy:['Academy','Nine lessons. One connected practice.'],journey:['Journey','Follow your curiosity. Keep your progress.'],toolkit:['Toolkit','Instruments for better thinking.'],seminars:['Workshops','A focused session. A tangible outcome.'],lesson:['Academy / Reading room','Learn · Example · Write · Check'],resource:['Toolkit / Resource guide','Adapt it to your research.'],workshop:['Workshops / Session guide','Your next hour, with intention.']};
 function mount(){const room=rooms[document.body.dataset.page];document.body.classList.toggle('learning-room',!!room);if(!room)return;const container=document.querySelector('#main .container');if(container&&!container.querySelector('.learning-edition')){const edition=document.createElement('div');edition.className='learning-edition';const label=document.createElement('span');label.textContent=room[0];const link=document.createElement('a');link.href=document.body.dataset.page==='academy'?'#journey':'#academy';link.textContent=document.body.dataset.page==='academy'?'Explore your journey':'Return to academy';edition.append(label,link);container.prepend(edition)}}
 addEventListener('rrh:route',mount);mount();
})();
